// Package disclosurephrase detects explicit statements of AI use, such as
// "Drafted with OpenAI Codex" or "AI disclosure: Claude assisted with tests",
// where a tool name appears inside wording that says the tool was used.
package disclosurephrase

import (
	"regexp"
	"strings"

	"github.com/chaoss/disclosure/detection"
	"github.com/chaoss/disclosure/detection/toolmention"
)

var (
	// "Drafted with", "Generated by", "Written using", "with the help of" right before the tool
	// name, or before one other tool it is listed with ("generated with Codex and Cursor").
	leadingPhrase = regexp.MustCompile(`(?i)(?:\b(?:drafted|generated|written|created|authored|co-?authored|assisted|produced|prepared|built)\s+(?:\w+\s+)?(?:with|by|using|via)|\bwith\s+(?:the\s+)?(?:help|assistance)\s+(?:of|from))\s+(?:the\s+)?(?:[\w.-]+(?:\s+[\w.-]+){0,2}(?:\s*,|\s+and|\s+or)\s+)?$`)
	// "Codex assisted", "Copilot was used" right after the tool name.
	trailingPhrase = regexp.MustCompile(`(?i)^\s+(?:was\s+used|assisted|helped|wrote|generated|drafted)\b`)
	// An "AI disclosure:" style label anywhere on the line.
	disclosureLabel = regexp.MustCompile(`(?i)\bAI[\s-]*(?:disclosure|assistance|usage|use)\s*:`)
)

type Detector struct {
	ConfidenceLevels map[detection.Confidence]float64
}

func (d *Detector) Name() string { return "disclosurephrase" }

func (d *Detector) GetConfidenceLevels() map[detection.Confidence]float64 { return d.ConfidenceLevels }

func (d *Detector) Detect(input detection.Input) []detection.Finding {
	text, err := input.GetTextWithCommitMessage()
	if err != nil {
		return nil
	}

	var findings []detection.Finding
	seen := map[string]bool{}
	for line := range strings.SplitSeq(text, "\n") {
		for _, m := range toolmention.Mentions(line) {
			if seen[m.Tool] || !disclosed(line, m) {
				continue
			}
			seen[m.Tool] = true
			score := detection.DisclosurePhraseBaseScore
			findings = append(findings, detection.Finding{
				Detector:   d.Name(),
				Tool:       m.Tool,
				Score:      score,
				Confidence: detection.ScoreToConfidence(d.ConfidenceLevels, score),
				Detail:     "text states " + m.Tool + " was used",
			})
		}
	}
	return findings
}

func disclosed(line string, m toolmention.Mention) bool {
	return leadingPhrase.MatchString(line[:m.Start]) ||
		trailingPhrase.MatchString(line[m.End:]) ||
		disclosureLabel.MatchString(line)
}
